40: function distanceKm([lng1, lat1]: Position, [lng2, lat2]: Position) {
41:   const kmPerDegLat = 111.2;
42:   const kmPerDegLng = kmPerDegLat * Math.cos(((lat1 + lat2) / 2) * (Math.PI / 180));
43:   return Math.hypot((lng1 - lng2) * kmPerDegLng, (lat1 - lat2) * kmPerDegLat);
