46: export function computeLayers(
47:   shapes: TractShapes,
48:   fit: AudienceFit,
49:   campaigns: Campaign[],
50: ): TractLayers {
51:   const stations: Position[] = campaigns.flatMap((c) =>
52:     c.station ? [[c.station.longitude, c.station.latitude] as Position] : [],
53:   );
54:   const layers: TractLayers = {};
55:   for (const feature of shapes.features) {
56:     const { geoid } = feature.properties;
57:     const audience = fit.scores[geoid];
58:     if (audience === undefined) continue;
59:     const here = centre(feature.geometry);
60:     let competition = 0;
61:     for (const s of stations) {
62:       const d = distanceKm(here, s) / CAMPAIGN_REACH_KM;
63:       competition = Math.max(competition, Math.exp(-d * d));
64:     }
65:     layers[geoid] = {
66:       fit: audience,
67:       competition,
68:       gap: audience * (1 - competition),
69:     };
70:   }
71:   return layers;
72: }
