import { readFile } from "node:fs/promises";
import path from "node:path";

const ANALYSIS_DIR = path.join(process.cwd(), "..", "data", "analysis");

/** Parses the CSV files `tools.analyze` writes, which contain no quoted fields. */
export async function readAnalysisCsv(name: string) {
  const text = await readFile(path.join(ANALYSIS_DIR, name), "utf8");
  const [header, ...lines] = text.trim().split("\n");
  const keys = header.split(",");
  return lines.map((line) => {
    const values = line.split(",");
    return Object.fromEntries(keys.map((k, i) => [k, values[i] ?? ""]));
  });
}

export async function readAnalysisJson<T>(name: string): Promise<T> {
  return JSON.parse(await readFile(path.join(ANALYSIS_DIR, name), "utf8"));
}

/** A number from 0 to 1 that depends only on the string, so stand-in output is stable between runs. */
export function hashUnit(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) / 4294967296;
}

export const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));

"use server";

// Stand-in for the placements Server Function. It reads the real kiosk and
// shelter data but invents costs, measurement methods and minimum spends.

import type { Borough, Placement, PlacementQuery } from "@/lib/contract";

import { delay, hashUnit, readAnalysisCsv } from "@/lib/data";

const MEASUREMENTS: Placement["measurement"][] = ["QR code", "promo code", "landing page"];

export async function findPlacements(query: PlacementQuery): Promise<Placement[]> {
  const rows = await readAnalysisCsv("nyc_placements.csv");
  const rank = new Map(query.geoids.map((g, i) => [g, i]));

  const placements: Placement[] = rows
    .filter((r) => rank.has(r.geoid) && r.carries_ads !== "no")
    .map((r) => {
      const base = r.kind === "linknyc" ? 0.02 : 0.035;
      return {
        id: r.placement_id,
        kind: r.kind as Placement["kind"],
        address: r.address,
        borough: r.borough as Borough,
        latitude: Number(r.latitude),
        longitude: Number(r.longitude),
        geoid: r.geoid,
        carriesAds: r.carries_ads as Placement["carriesAds"],
        costPerAudienceMember: Number((base * (0.6 + hashUnit(r.placement_id))).toFixed(3)),
        measurement: MEASUREMENTS[Math.floor(hashUnit(r.placement_id + "m") * 3)],
      };
    });

  // Stand-in minimum spends: a budget under $2,000 a month rules out bus shelters.
  const affordable = placements.filter(
    (p) => query.monthlyBudget >= 2000 || p.kind === "linknyc",
  );
  affordable.sort(
    (a, b) =>
      rank.get(a.geoid)! - rank.get(b.geoid)! ||
      a.costPerAudienceMember - b.costPerAudienceMember,
  );

  await delay(400);
  return affordable.slice(0, 12);
}

"use server";

// Scores the target-customer sentence against the tract columns with OpenAI's
// Decisions API, then combines the real tract numbers in code. The model never
// sees a tract.

import { openai } from "@ai-sdk/openai";
import { experimental_decide as decide } from "ai";

import type { AudienceFit, Brief, ColumnWeight, Measure } from "@/lib/contract";
import { readAnalysisCsv, readAnalysisJson } from "@/lib/data";

type Column = {
  name: string;
  scaled: string;
  description: string;
  measures: Measure;
};

/**
 * How a column can push an area up or down for one target customer. The
 * direction belongs to the customer, not the column: a high income is good for
 * an affluent audience and bad for a low-income one, and `median_age` points
 * the opposite way for young and older audiences. Flattening these to positive
 * weights would make the product unable to describe either end of those
 * ranges, so the score question asks for direction and the weight keeps its
 * sign.
 */
const LEVELS = [
  "Strongly against: the target customers are much less likely to have this trait.",
  "Against: the target customers are somewhat less likely to have this trait.",
  "Not relevant: the sentence says nothing either way about this trait.",
  "For: the target customers are somewhat more likely to have this trait.",
  "Strongly for: the target customers are much more likely to have this trait.",
];

const MODEL = openai.decisionModel("gpt-6-luna");

export async function scoreAudience(brief: Brief): Promise<AudienceFit> {
  try {
    return await score(brief);
  } catch (error) {
    console.error("Audience scoring failed", error);
    throw new Error(
      `Audience scoring failed: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
}

async function score(brief: Brief): Promise<AudienceFit> {
  const [columns, tracts] = await Promise.all([
    readAnalysisJson<Column[]>("columns.json"),
    readAnalysisCsv("nyc_tracts.csv"),
  ]);

  const result = await decide({
    model: MODEL,
    state: brief.targetCustomer,
    questions: Object.fromEntries(
      columns.map((column) => [
        column.name,
        {
          type: "score" as const,
          instructions: `How does this trait relate to the target customers? Trait: ${column.description}.`,
          criteria: LEVELS,
        },
      ]),
    ),
  });

  const weights: ColumnWeight[] = columns.map((column) => {
    const answer = result.answers[column.name];
    if (answer?.type !== "score") {
      throw new Error(`The model returned no score for "${column.name}".`);
    }
    const signed = (answer.score / (LEVELS.length - 1)) * 2 - 1;
    return {
      column: column.name,
      description: column.description,
      measures: column.measures,
      weight: Number(Math.min(1, Math.max(-1, signed)).toFixed(2)),
    };
  });

  const markets = new Set<string>(brief.markets);
  const raw: [string, number][] = [];
  for (const tract of tracts) {
    if (!markets.has(tract.borough)) continue;
    let sum = 0;
    let magnitude = 0;
    for (const [i, w] of weights.entries()) {
      if (w.weight === 0) continue;
      sum += w.weight * Number(tract[columns[i].scaled]);
      magnitude += Math.abs(w.weight);
    }
    raw.push([tract.geoid, magnitude ? sum / magnitude : 0]);
  }

  // Rescale by rank so the strongest tracts reach 1 whatever the weights.
  raw.sort((a, b) => a[1] - b[1]);
  const scores: Record<string, number> = {};
  raw.forEach(([geoid], i) => {
    scores[geoid] = Number((i / Math.max(raw.length - 1, 1)).toFixed(4));
  });

  return { weights, scores };
}

// The only module the UI imports server calls from. Audience scoring is real;
// placements and the competitor agent are still stand-ins in `stand-in/`.

export { scoreAudience } from "@/lib/server/audience";
export { findPlacements } from "@/lib/stand-in/placements";
export { runCompetitorAgent } from "@/lib/stand-in/competitor-agent";

